async def act(page):
    import asyncio

    # Incrementally scroll to the bottom so any lazy-loaded content or pagination controls appear.
    await page.evaluate(
        """async () => {
            const step = 600;
            const delay = ms => new Promise(r => setTimeout(r, ms));
            while ((window.innerHeight + window.scrollY) < document.body.scrollHeight) {
                window.scrollBy(0, step);
                await delay(100);
            }
            // ensure exact bottom and give a small pause for lazy content
            window.scrollTo(0, document.body.scrollHeight);
            await delay(250);
        }"""
    )

    # Small pause to allow the page to settle after scrolling
    await asyncio.sleep(0.25)

